</div>
<div style="padding:12px 14px 8px;">
<script>
(function(){
  var _cs = document.currentScript;
  function el(tag, attrs, txt){
    var e = document.createElementNS("http://www.w3.org/2000/svg", tag);
    for (var k in attrs) e.setAttribute(k, attrs[k]);
    if (txt !== undefined) e.textContent = txt;
    return e;
  }
  var FONT = "-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif";
  function tx(str, x, y, size, weight, fill, anchor){
    return el("text", {x:x, y:y, "font-family":FONT, "font-size":size, "font-weight":weight, fill:fill, "text-anchor":anchor}, str);
  }
  function tw(str, size, numeric){ return Math.ceil(str.length * size * (numeric ? 0.58 : 0.68)); }
  var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
  svg.setAttribute("viewBox","0 0 680 300");
  svg.setAttribute("width","100%");
  var margin = {left:62, right:24, top:18, bottom:46};
  var PW = 680 - margin.left - margin.right;
  var PH = 300 - margin.top - margin.bottom;
  var vals = [2,2,1,1,1,1,1,1,1,1,2,3,4,5,5,5,6,6,5,5,4,4,3,3,3,3,3,3];
  var n = vals.length;
  var lo = Math.floor(Math.min.apply(null, vals) - 0.5);
  var hi = Math.ceil(Math.max.apply(null, vals) + 0.5);
  function xp(i){ return margin.left + (i / (n - 1)) * PW; }
  function yp(v){ return margin.top + ((hi - v) / (hi - lo)) * PH; }
  var plotBottom = margin.top + PH;
  var lastVal = vals[n - 1];
  var peakIdx = vals.indexOf(Math.max.apply(null, vals));
  var bands = [{a:10, b:17, fill:"#c0392b", op:0.05, label:"HAUSSE\u00a0: 1 À 6\u00a0%"}, {a:22, b:27, fill:"#2e7d32", op:0.07, label:"6 TRIM. À 3\u00a0%"}];
  bands.forEach(function(bd){
    svg.appendChild(el("rect", {x:xp(bd.a), y:margin.top, width:xp(bd.b) - xp(bd.a), height:PH, fill:bd.fill, "fill-opacity":bd.op}));
  });
  var ticks = [];
  for (var t = lo; t <= hi; t += 1) { if (t !== lastVal) ticks.push(t); }
  ticks.forEach(function(tk){
    svg.appendChild(el("line", {x1:margin.left, x2:margin.left + PW, y1:yp(tk), y2:yp(tk), stroke:"#ececec", "stroke-width":0.5}));
  });
  var d = "M" + xp(0).toFixed(1) + " " + yp(vals[0]).toFixed(1) + " ";
  for (var i = 1; i < n; i++) {
    d += "L" + xp(i).toFixed(1) + " " + yp(vals[i - 1]).toFixed(1) + " L" + xp(i).toFixed(1) + " " + yp(vals[i]).toFixed(1) + " ";
  }
  svg.appendChild(el("path", {d:d, fill:"none", stroke:"#4a5568", "stroke-width":2, "stroke-linejoin":"round"}));
  svg.appendChild(el("line", {x1:margin.left, x2:margin.left + PW, y1:plotBottom, y2:plotBottom, stroke:"#d8d8d8", "stroke-width":1}));
  svg.appendChild(el("line", {x1:margin.left, x2:margin.left, y1:margin.top, y2:plotBottom, stroke:"#d8d8d8", "stroke-width":1}));
  var lastX = xp(n - 1);
  var lastY = yp(lastVal);
  svg.appendChild(el("circle", {cx:lastX, cy:lastY, r:4, fill:"#4a5568", stroke:"#ffffff", "stroke-width":1}));
  var pillH = 16;
  var pillText = lastVal + "\u00a0%";
  var pillW = tw(pillText, 9, true) + 10;
  var pillX = lastX - pillW - 6;
  if (pillX < margin.left) pillX = margin.left;
  var pillY = lastY - pillH / 2;
  svg.appendChild(el("rect", {x:pillX, y:pillY, width:pillW, height:pillH, rx:3, fill:"#e8a825"}));
  svg.appendChild(tx(pillText, pillX + pillW / 2, pillY + pillH / 2 + 4, 9, 700, "#111111", "middle"));
  ticks.forEach(function(tk){
    svg.appendChild(tx(tk + "\u00a0%", margin.left - 6, yp(tk) + 3, 8.5, 400, "#aaaaaa", "end"));
  });
  for (var j = 0; j < n; j++) {
    var lbl = (j % 4 === 0) ? String(2020 + j / 4) : "";
    if (lbl) svg.appendChild(tx(lbl, xp(j), plotBottom + 14, 8, 400, "#999999", "middle"));
  }
  bands.forEach(function(bd){
    svg.appendChild(tx(bd.label, (xp(bd.a) + xp(bd.b)) / 2, margin.top + 10, 7, 700, bd.fill, "middle"));
  });
  svg.appendChild(tx("SOMMET 6\u00a0%", xp(peakIdx + 0.5), yp(vals[peakIdx]) - 8, 8, 400, "#444444", "middle"));
  _cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source&nbsp;: taux d’intérêt prescrits de l’ARC, historique trimestriel compilé par WealthNorth.ca&nbsp;; Investment Executive (taux du T4 2026). &nbsp;|&nbsp; hdq.ca</div>
</div>
</div>
<p style="font-size:11px;color:#666;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;margin-top:6px;">Le taux correspond au rendement moyen des bons du Trésor du gouvernement du Canada à 90 jours au cours du premier mois du trimestre précédent, arrondi au point de pourcentage supérieur. Le taux sur les impôts en souffrance est fixé quatre points plus haut, soit 7&nbsp;% pour le T4 2026.</p>
<h2>L’arithmétique de l’écart</h2>
<p>Prenons un conjoint situé dans la tranche fédérale de 29&nbsp;%, qui couvre les revenus de 181&nbsp;440&nbsp;$ à 258&nbsp;482&nbsp;$, et qui prête 500&nbsp;000&nbsp;$ à 3&nbsp;% à un conjoint situé dans la tranche fédérale de 14&nbsp;%, qui couvre les revenus jusqu’à 58&nbsp;523&nbsp;$. L’emprunteur investit la somme dans un compte non enregistré et verse 15&nbsp;000&nbsp;$ d’intérêt au plus tard le 30 janvier. Le prêteur déclare cet intérêt comme revenu et l’emprunteur le déduit.</p>
<p>Seul le rendement supérieur à 3&nbsp;% passe d’une déclaration de revenus à l’autre. Chaque point de pourcentage de rendement du portefeuille au-dessus du taux transfère 5&nbsp;000&nbsp;$ de revenu vers la tranche inférieure, soit 750&nbsp;$ par année d’impôt fédéral avec un écart de 15 points entre les tranches, avant l’impôt provincial. Un portefeuille dont le rendement est inférieur à 3&nbsp;% ne procure aucun avantage, ce qui explique qu’un prêt consenti à 6&nbsp;% au début de 2024 impose un seuil deux fois plus élevé.</p>
<h2>Les comptes enregistrés d’abord</h2>
<p>La stratégie s’applique aux sommes non enregistrées. Le plafond du CELI est de 7&nbsp;000&nbsp;$ pour 2026, avec des droits de cotisation cumulatifs de 109&nbsp;000&nbsp;$ pour une personne admissible depuis 2009, et la croissance dans le compte est libre d’impôt sans aucun prêt. Le plafond de cotisation au REER est de 33&nbsp;810&nbsp;$ pour 2026 et passe à 35&nbsp;390&nbsp;$ pour 2027, selon l’ARC. Les ménages qui disposent de droits inutilisés dans l’un ou l’autre de ces comptes ont un moyen plus simple d’obtenir le même abri fiscal, et un prêt à taux prescrit ajoute une étape de conformité dont les comptes enregistrés sont exempts.</p>
<p>Les prêts d’un actionnaire à une société relèvent d’autres règles et sont exclus de cette stratégie, conçue pour les particuliers et les fiducies familiales.</p>
<h2>Deux dates et un piège</h2>
<p>Le 31 décembre est le dernier jour du trimestre où le taux de 3&nbsp;% est assuré. Le 30 janvier 2027 est la date limite pour payer intégralement l’intérêt de la première année, et cette échéance revient chaque 30 janvier pendant toute la durée du prêt. Si l’intérêt n’est pas payé en entier à cette date, quelle que soit l’année, les règles d’attribution s’appliquent pour cette année et toutes les suivantes, et le fractionnement du revenu est perdu.</p>
<p>Les prêts consentis du premier trimestre de 2023 au deuxième trimestre de 2025 portent des taux de 4&nbsp;% à 6&nbsp;% aussi longtemps qu’ils sont en cours. Les ménages qui en détiennent peuvent comparer le taux existant à 3&nbsp;%, mais rembourser puis prêter de nouveau exige de déplacer des actifs, ce qui peut entraîner la réalisation de gains en capital.</p>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Ce qu’ils ressentent</div>
<p>Les ménages qui ont lu sur le fractionnement du revenu en ligne éprouvent deux choses à la fois&nbsp;: le sentiment qu’il existe une règle dont ils ne se prévalent pas, et la crainte qu’une erreur auprès de l’ARC, en particulier un paiement d’intérêt manqué, coûte plus cher que ce que la stratégie permet d’économiser. Ceux qui ont mis en place des prêts à 5&nbsp;% ou à 6&nbsp;% en 2023 ou en 2024 peuvent aussi avoir l’impression d’avoir figé leur taux au mauvais moment.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Quoi dire</div>
<div class="script-box">Le taux prescrit de l’ARC est de 3&nbsp;% pour le quatrième trimestre, soit la moitié de ce qu’il était au début de 2024. Cela compte pour une stratégie en particulier&nbsp;: un prêt familial du conjoint dont le revenu est le plus élevé au conjoint dont le revenu est le plus bas ou à une fiducie familiale. Le taux est fixé le jour où le prêt est consenti, et le seul revenu qui passe d’une déclaration à l’autre est le rendement supérieur à ce taux. Sur 500&nbsp;000&nbsp;$, chaque point de rendement au-dessus de 3&nbsp;% transfère 5&nbsp;000&nbsp;$ de revenu, ce qui vaut environ 750&nbsp;$ par année d’impôt fédéral lorsque vos tranches sont distantes de 15 points. La stratégie ne fonctionne que si l’intérêt est payé en entier au plus tard le 30 janvier de chaque année. J’aimerais vérifier si vos actifs non enregistrés et vos droits de cotisation au CELI et au REER justifient l’exercice, et le cas échéant, le 31 décembre est la date qui garantit le taux de 3&nbsp;%.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Qui est touché</div>
<p><strong>Forte incidence&nbsp;:</strong> Les couples dont un conjoint a un revenu supérieur à 181&nbsp;440&nbsp;$ et l’autre inférieur à 58&nbsp;523&nbsp;$, et qui détiennent au moins 250&nbsp;000&nbsp;$ d’actifs non enregistrés. Toute personne qui a un prêt à taux prescrit consenti à 4&nbsp;%, à 5&nbsp;% ou à 6&nbsp;%.</p>
<p><strong>Incidence variable&nbsp;:</strong> Les couples dont les revenus sont semblables ou dont les actifs non enregistrés sont modestes, et les ménages qui ont des droits inutilisés au CELI ou au REER, où les comptes enregistrés devraient être remplis en premier. Les propriétaires d’entreprise constituée en société, dont les prêts d’actionnaire obéissent à d’autres règles.</p>
<p><strong>Avantage potentiel&nbsp;:</strong> Les parents d’enfants mineurs qui envisagent une fiducie familiale, sous réserve des règles d’attribution et de revenu fractionné applicables aux mineurs et d’un avis juridique et fiscal sur la documentation.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Liste de vérification</div>
<div class="checklist-item">Dressez la liste des ménages dont un conjoint se situe au-dessus de la tranche fédérale de 29&nbsp;% et l’autre sous celle de 20,5&nbsp;%, et qui détiennent des actifs non enregistrés.</div>
<div class="checklist-item">Confirmez que les droits de cotisation au CELI et au REER ont été utilisés avant de proposer un prêt.</div>
<div class="checklist-item">Repérez les prêts à taux prescrit existants consentis à 4&nbsp;%, à 5&nbsp;% ou à 6&nbsp;% entre le T1 2023 et le T2 2025 et signalez-les pour un examen en vue d’un refinancement.</div>
<div class="checklist-item">Inscrivez au calendrier le 30 janvier 2027 pour chaque prêt et confirmez que l’emprunteur paie l’intérêt avec ses propres fonds.</div>
<div class="checklist-item">Dirigez les ménages intéressés vers leur fiscaliste pour la documentation du prêt avant le 31 décembre.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de suivi</div>
<div class="email-box" id="respond-email">
<strong>Objet&nbsp;:</strong> Le taux prescrit de 3&nbsp;% et un possible prêt familial<br><br>
Bonjour [Nom du client],<br><br>
Merci d’avoir discuté avec moi aujourd’hui. Je tenais à résumer ce dont nous avons parlé.<br><br>
Le taux prescrit de l’ARC est de 3&nbsp;% du 1er octobre au 31 décembre, un sixième trimestre de suite à ce niveau. Un prêt consenti à ce taux le conserve pendant toute la durée du prêt, et seul le rendement du placement supérieur à 3&nbsp;% passe d’une déclaration de revenus à l’autre. L’intérêt doit être payé en entier au plus tard le 30 janvier de chaque année, faute de quoi l’avantage est perdu.<br><br>
Avant de rien décider, j’aimerais confirmer vos droits de cotisation inutilisés au CELI et au REER et examiner vos avoirs non enregistrés. Dites-moi quel moment ce mois-ci vous conviendrait.<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''respond-email'', this)">Copier le courriel</button>
</div>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Profils de clients à cibler</div>
<p><strong>Couples dont le portefeuille imposable est important et dont les revenus sont inégaux&nbsp;:</strong> un conjoint dans une tranche fédérale supérieure, l’autre dans une tranche inférieure, et personne qui leur a expliqué que le taux du prêt est fixé le jour où il est consenti.</p>
<p><strong>Investisseurs autonomes qui ont mis en place un prêt familial par eux-mêmes&nbsp;:</strong> le paiement du 30 janvier est l’étape le plus souvent oubliée, et un seul oubli met fin à la protection.</p>
<p><strong>Détenteurs de prêts de 2023 et de 2024 à 5&nbsp;% ou à 6&nbsp;%&nbsp;:</strong> ils ignorent peut-être que le taux est maintenant de 3&nbsp;%.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Phrase d’accroche</div>
<div class="script-box">Je vous appelle parce que le taux prescrit de l’ARC est de 3&nbsp;% pour un autre trimestre, soit la moitié de ce qu’il était au début de 2024, et que la plupart des couples dont le portefeuille imposable est important ignorent que le taux est fixé à la date d’un prêt familial. Est-ce que quelqu’un vous a déjà expliqué cela&nbsp;?</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Proposition de valeur</div>
<p>Un prêt à taux prescrit est une petite stratégie assortie d’une exigence de conformité rigoureuse. Les économies ne viennent que du rendement supérieur au taux, et elles disparaissent si l’intérêt n’est pas payé au plus tard le 30 janvier, quelle que soit l’année. Un ménage autonome porte seul tout ce risque.</p>
<p>La valeur du conseiller tient à la séquence&nbsp;: les droits de cotisation aux comptes enregistrés d’abord, puis le prêt, puis un calendrier de paiement et une documentation examinée par un fiscaliste. Comme le taux du T1 2027 sera établi par les adjudications de bons du Trésor d’octobre, la discussion arrive à propos sans être précipitée.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Questions de découverte</div>
<div class="checklist-item">Vos revenus et ceux de votre conjoint ou partenaire sont-ils sensiblement différents&nbsp;?</div>
<div class="checklist-item">Combien détenez-vous dans des comptes non enregistrés, et de combien de droits de cotisation inutilisés au CELI et au REER disposez-vous&nbsp;?</div>
<div class="checklist-item">Avez-vous déjà prêté de l’argent à un conjoint ou à une fiducie familiale pour investir, et à quel taux&nbsp;?</div>
<div class="checklist-item">Qui suit le paiement de l’intérêt du 30 janvier, et que se passe-t-il s’il est manqué&nbsp;?</div>
<div class="checklist-item">Quel rendement obtenez-vous actuellement sur vos placements imposables&nbsp;?</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de prospection</div>
<div class="email-box" id="prospect-email">
<strong>Objet&nbsp;:</strong> Le taux de l’ARC fixé le jour où un prêt familial est consenti<br><br>
Bonjour [Nom],<br><br>
Le taux prescrit de l’ARC est de 3&nbsp;% jusqu’au 31 décembre, un sixième trimestre de suite, en baisse par rapport à 6&nbsp;% au début de 2024. Pour les couples dont les revenus sont inégaux et qui détiennent un portefeuille imposable, un prêt familial consenti à ce taux le conserve pendant toute la durée du prêt, pourvu que l’intérêt soit payé au plus tard le 30 janvier de chaque année.<br><br>
Cette stratégie ne convient pas à tout le monde, et les comptes enregistrés passent généralement en premier. Si vous voulez savoir si elle s’applique à votre situation, je serai heureux de passer en revue les chiffres lors d’un appel de 20 minutes.<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''prospect-email'', this)">Copier le courriel</button>
</div>',
  '[{"value":"3 %","label":"Taux prescrit du T4 2026"},{"value":"6 %","label":"Sommet du début de 2024"},{"value":"6e","label":"Trimestre consécutif à 3 %"},{"value":"30 janv.","label":"Échéance du paiement d’intérêt"}]',
