  svg.appendChild(tx("SEPT.\u00a0: -2,85\u00a0%", (bandX + margin.left + PW) / 2, priceBottom - 6, 7, 700, "#c0392b", "middle"));
  svg.appendChild(tx("MM 10J", lastX - 4, yp(maLast) - 6, 7.5, 400, "#888888", "end"));
